const clampTo = (value, [min, max]) => Math.min(max, Math.max(min, value));
const numberOr = (value, fallback) => (Number.isFinite(Number(value)) ? Number(value) : fallback);
const listOf = (value, allowed) => (Array.isArray(value) ? value.filter((v) => allowed.includes(v)) : []);

/**
 * Settings made safe to build: every key present, numbers in range, and the few that depend on others brought in
 * line. Returns the settings and what had to change, in words.
 */
export function normalize(input) {
  const raw = input && typeof input === "object" ? input : {};
  const p = { ...DEFAULTS };
  const notes = [];
  for (const key of Object.keys(DEFAULTS)) {
    if (raw[key] === undefined) continue;
    const fallback = DEFAULTS[key];
    if (typeof fallback === "number") p[key] = numberOr(raw[key], fallback);
    else if (typeof fallback === "boolean") p[key] = Boolean(raw[key]);
    else if (typeof fallback === "string") p[key] = String(raw[key]);
    else p[key] = raw[key];
  }
  for (const [key, range] of Object.entries(RANGES)) if (key in p) p[key] = clampTo(p[key], range);
  // PrintCasing's: a PCB on the lid is pcbWall "lid", or pcbOnLid.
  if (raw.pcbWall === "lid") p.pcbOnLid = true;
  p.lidType = ["flat", "lip"].includes(p.lidType) ? p.lidType : "lip";
  p.lidFixation = ["screws", "snap", "snapJoint"].includes(p.lidFixation) ? p.lidFixation : "screws";
  p.ventPattern = ["slots", "honeycomb", "dots", "diamonds"].includes(p.ventPattern) ? p.ventPattern : "slots";
  p.ventOrientation = p.ventOrientation === "Y" ? "Y" : "X";
  p.textPlacement = ["lid", "front", "back", "left", "right"].includes(p.textPlacement) ? p.textPlacement : "lid";
  p.textType = p.textType === "emboss" ? "emboss" : "deboss";
  p.standoffMode = p.standoffMode === "list" ? "list" : "grid";
  p.latchWalls = listOf(p.latchWalls, WALLS);
  p.flangeWalls = listOf(p.flangeWalls, WALLS);
  p.ventWalls = listOf(p.ventWalls, WALLS);
  // PrintCasing keeps the lid's vents in ventSurfaces with the walls'.
  if (Array.isArray(raw.ventSurfaces) && raw.ventSurfaces.length) {
    p.hasVentilation = raw.ventSurfaces.includes("lid");
    p.ventWalls = listOf(raw.ventSurfaces, WALLS);
  }
  p.grooveWall = ["auto", ...WALLS].includes(p.grooveWall) ? p.grooveWall : "auto";
  p.textString = p.textString.slice(0, 40);
  p.pcbStandoffs = (Array.isArray(p.pcbStandoffs) ? p.pcbStandoffs : []).slice(0, 24).map((s, i) => ({
    id: String(s?.id ?? `s${i + 1}`),
    x: clampTo(numberOr(s?.x, 0), RANGES.standoffX),
    y: clampTo(numberOr(s?.y, 0), RANGES.standoffY),
    height: clampTo(numberOr(s?.height, 6), RANGES.standoffHeight),
    outerDia: clampTo(numberOr(s?.outerDia, 6), RANGES.standoffOuterDia),
    innerDia: clampTo(numberOr(s?.innerDia, 2.5), RANGES.standoffInnerDia),
  }));
  p.cutouts = (Array.isArray(p.cutouts) ? p.cutouts : []).slice(0, 40).map((c, i) => ({
    id: String(c?.id ?? `c${i + 1}`),
    wall: [...WALLS, "lid"].includes(c?.wall) ? c.wall : "front",
    shape: ["rect", "circle", "type-c", "dsub", "hdmi", "xt60"].includes(c?.shape) ? c.shape : "rect",
    width: clampTo(numberOr(c?.width, 10), RANGES.cutoutWidth),
    height: clampTo(numberOr(c?.height, 6), RANGES.cutoutHeight),
    diameter: clampTo(numberOr(c?.diameter, 8), RANGES.cutoutDiameter),
    rotation: numberOr(c?.rotation, 0),
    x: numberOr(c?.x, 0),
    z: numberOr(c?.z, 0),
    portTemplate: c?.portTemplate ? String(c.portTemplate) : null,
    label: c?.label ? String(c.label).slice(0, 16) : "",
    labelPosition: ["above", "below", "left", "right"].includes(c?.labelPosition) ? c.labelPosition : "above",
    labelSize: clampTo(numberOr(c?.labelSize, 3.5), RANGES.cutoutLabelSize),
  }));

  // What depends on other settings.
  const maxRadius = Math.floor(Math.min(p.width, p.length) / 2);
  if (p.radius > maxRadius) {
    notes.push(`Corner radius held to ${maxRadius} mm, half the box's shorter side.`);
    p.radius = maxRadius;
  }
  const minInset = Number((p.thickness + p.bossRadius).toFixed(2));
  if (p.bossInset < minInset) p.bossInset = minInset;
  const innerW = p.width - p.thickness * 2;
  const innerL = p.length - p.thickness * 2;
  if (p.pcbWidth > innerW - 10) p.pcbWidth = Math.max(10, Math.floor(innerW - 10));
  if (p.pcbLength > innerL - 10) p.pcbLength = Math.max(10, Math.floor(innerL - 10));
  if (p.lidFixation !== "screws" && p.lidType === "flat") {
    notes.push("Snap fixings need the lid's lip, so the lid has one.");
    p.lidType = "lip";
  }
  return { params: p, notes };
}

// ---- enclosure.js ----

// The enclosure itself: its base and lid as solids, from the settings. The base is a rounded box with its inside taken
// out, less what stands inside it (screw bosses, PCB standoffs, snap ridges), with holes cut through it; the lid is a
// plate, with a lip that drops inside the base when it has one.
//
// x runs across the width, y along the length (the front faces -y) and z up; the base stands on z = 0 and the lid
// sits on top of it, at z = height.


const UP = [0, 0, 1];
/** PLA's density, g/cm³. */
const PLA = 1.24;

/**
 * Each wall seen from outside: its outward normal, the way along it from left to right, its length, and its outer
 * face's distance from the centre.
 */
function wallsOf(W, L) {
  return {
    front: { n: [0, -1, 0], u: [1, 0, 0], length: W, half: L / 2 },
    back: { n: [0, 1, 0], u: [-1, 0, 0], length: W, half: L / 2 },
    left: { n: [-1, 0, 0], u: [0, -1, 0], length: L, half: W / 2 },
    right: { n: [1, 0, 0], u: [0, 1, 0], length: L, half: W / 2 },
  };
}

/** The point on a wall's outer face `x` from its left end and `z` up. */
const onWall = (wall, x, z) =>
  [0, 1, 2].map((i) => wall.n[i] * wall.half + wall.u[i] * (x - wall.length / 2) + UP[i] * z);

/**
 * A prism of `outline` drawn on a wall's outer face around (x, z), from `d0` to `d1` outward: negative is into the wall.
 */
const wallPrism = (wall, outline, x, z, d0, d1) => prismIn(outline, onWall(wall, x, z), wall.u, UP, d0, d1);

/** A cutout's opening, centred. */
function cutoutOutline(c, quality) {
  let outline;
  if (c.shape === "circle") outline = circle(c.diameter / 2, segmentsFor(c.diameter / 2, quality));
  else if (c.shape === "type-c") outline = stadium(c.width, c.height, quality);
  else if (c.shape === "dsub") outline = trapezoid(c.width, c.height);
  else if (c.shape === "hdmi") outline = chamferedBottom(c.width, c.height, c.height * 0.3);
  else if (c.shape === "xt60") outline = chamferedBottom(c.width, c.height, c.height * 0.35);
  else outline = roundedRect(c.width, c.height, Math.min(0.5, c.width / 4, c.height / 4), quality);
  return rotate2(outline, c.rotation);
}

/** A cutout's extent from its centre, for placing its label. */
function cutoutHalf(c) {
  if (c.shape === "circle") return [c.diameter / 2, c.diameter / 2];
  const a = (c.rotation * Math.PI) / 180;
  const [cs, sn] = [Math.abs(Math.cos(a)), Math.abs(Math.sin(a))];
  return [(c.width * cs + c.height * sn) / 2, (c.width * sn + c.height * cs) / 2];
}

/** Holes in a pattern filling a `long` × `wide` area, centred, `long` along the first axis. */
function ventOutlines(p, long, wide, quality) {
  const w = p.ventSlotWidth;
  const s = p.ventSlotSpacing;
  if (p.ventPattern === "slots") {
    const count = Math.max(1, Math.min(p.ventSlotCount, Math.floor((wide + s) / (w + s))));
    const span = count * w + (count - 1) * s;
    return Array.from({ length: count }, (_, i) =>
      move2(stadium(long, w, quality), 0, -span / 2 + w / 2 + i * (w + s)),
    );
  }
  // Holes of one size in rows: dots, diamonds, or hexagons offset in alternate rows.
  const size = Math.max(2, w * 1.5);
  const pitch = size + s;
  const cols = Math.max(1, Math.floor((long + s) / pitch));
  const rowPitch = p.ventPattern === "honeycomb" ? pitch * 0.866 : pitch;
  const rows = Math.max(1, Math.floor((wide - size) / rowPitch) + 1);
  const shape =
    p.ventPattern === "dots"
      ? circle(size / 2, Math.max(12, segmentsFor(size / 2, quality)))
      : p.ventPattern === "diamonds"
        ? [
            [size / 2, 0],
            [0, size / 2],
            [-size / 2, 0],
            [0, -size / 2],
          ]
        : rotate2(circle(size / 2, 6), 30);
  const out = [];
  for (let r = 0; r < rows && out.length < 400; r++) {
    const offset = p.ventPattern === "honeycomb" && r % 2 ? pitch / 2 : 0;
    const n = offset ? cols - 1 : cols;
    for (let c = 0; c < n; c++) {
      const x = -((cols - 1) * pitch) / 2 + offset + c * pitch;
      const y = -((rows - 1) * rowPitch) / 2 + r * rowPitch;
      out.push(move2(shape, x, y));
    }
  }
  return out;
}

/**
 * A wedge for a snap fit: `section` is its outline across the wall, as [outward, up] points from the wall's outer face,
 * run along the wall `width` wide around `x`.
 */
function wedge(wall, x, width, section) {
  // Drawn in the plane of (outward, up), which runs along the wall the other way: from x + width/2 back.
  const area = section.reduce((sum, [d, z], i) => {
    const [d2, z2] = section[(i + 1) % section.length];
    return sum + d * z2 - d2 * z;
  }, 0);
  return prismIn(area > 0 ? section : section.slice().reverse(), onWall(wall, x + width / 2, 0), wall.n, UP, 0, width);
}

/**
 * The enclosure's base and lid, as triangles ready to print or draw, and what to know about them.
 * `quality` is "draft", "normal" or "high": how finely curves are cut.
 */
export function buildEnclosure(input, { quality = "normal" } = {}) {
  const { params: p, notes } = normalize(input);
  const warnings = [...notes];
  const W = p.width;
  const L = p.length;
  const H = p.height;
  const t = p.thickness;
  const tol = p.tolerance;
  const walls = wallsOf(W, L);
  const innerW = W - 2 * t;
  const innerL = L - 2 * t;
  const innerR = Math.max(0, p.radius - t);
  const q = quality;

  const lid = p.hasLid;
  const lip = lid && p.lidType === "lip";
  const screws = lid && p.lidFixation === "screws" && p.hasCornerScrews;
  const snap = lid && lip && p.lidFixation === "snap";
  const snapJoint = lid && lip && p.lidFixation === "snapJoint";
  const lipH = lip ? (snap || snapJoint ? Math.max(p.lidLipHeight, p.latchHeight + 2) : p.lidLipHeight) : 0;
  const lt = p.lidThickness;
  const lidTop = H + lt;

  const inside = []; // stands inside the base: taken from its hollow
  const baseAdd = []; // joined to the base's outside
  const baseHoles = [];
  const lidAdd = [];
  const lidHoles = [];
  const lipCuts = [];

  // ---- corner screws -----------------------------------------------------------------------------------------
  const corners = [
    [1, 1],
    [-1, 1],
    [-1, -1],
    [1, -1],
  ].map(([sx, sy]) => [sx * (W / 2 - p.bossInset), sy * (L / 2 - p.bossInset), sx, sy]);
  if (screws) {
    for (const [x, y, sx, sy] of corners) {
      // The boss, and a block tying it to the corner of the walls.
      inside.push(cylinder(x, y, p.bossRadius, t - 0.5, H + 1, q));
      inside.push(
        box(
          Math.min(x, sx * (W / 2 - t / 2)),
          Math.min(y, sy * (L / 2 - t / 2)),
          t - 0.5,
          Math.max(x, sx * (W / 2 - t / 2)),
          Math.max(y, sy * (L / 2 - t / 2)),
          H + 1,
        ),
      );
      baseHoles.push(cylinder(x, y, p.screwDiameter / 2, Math.min(t + 1, H - 2), H + 1, q));
      lidHoles.push(cylinder(x, y, p.lidScrewDiameter / 2, H - lipH - 1, lidTop + 1, q));
      if (p.screwHeadDepth > 0)
        lidHoles.push(
          cylinder(x, y, p.screwHeadDiameter / 2, lidTop - Math.min(p.screwHeadDepth, lt - 0.6), lidTop + 1, q),
        );
      if (lip) {
        lipCuts.push(cylinder(x, y, p.bossRadius + tol, H - lipH - 1, H + 0.5, q));
        lipCuts.push(
          box(
            Math.min(x, sx * (W / 2)),
            Math.min(y, sy * (L / 2)),
            H - lipH - 1,
            Math.max(x, sx * (W / 2)),
            Math.max(y, sy * (L / 2)),
            H + 0.5,
          ),
        );
      }
    }
    if (p.screwHeadDiameter <= p.lidScrewDiameter) warnings.push("warn.screwHeads");
  }

  // ---- snap fits ---------------------------------------------------------------------------------------------
  const latchWalls = p.latchWalls.length ? p.latchWalls : ["left", "right"];
  const latchSpots = [];
  if (snap || snapJoint) {
    for (const name of latchWalls) {
      const wall = walls[name];
      const usable = wall.length - 2 * Math.max(p.radius, t) - p.latchWidth;
      for (let i = 0; i < p.latchCount; i++) {
        const x = wall.length / 2 + (p.latchCount === 1 ? 0 : -usable / 2 + (usable * i) / (p.latchCount - 1));
        latchSpots.push([wall, x]);
      }
    }
    const hw = Math.max(1.2, p.latchHeight * 0.4);
    const zb = H - lipH + 1.2;
    const lipOuter = -(t + tol);
    if (snap) {
      // Ridges on the base's walls, sloped on top; windows in the lip they click into.
      for (const [wall, x] of latchSpots) {
        const h = hw - 2 * tol;
        inside.push(
          wedge(wall, x, p.latchWidth, [
            [-t + 0.4, zb + tol],
            [-t - p.latchDepth, zb + tol],
            [-t + 0.4, zb + tol + h + p.latchDepth],
          ]),
        );
        lipCuts.push(
          wallPrism(
            wall,
            roundedRect(p.latchWidth + 2 * tol + 0.4, hw, 0, q),
            x,
            zb + hw / 2,
            lipOuter - p.lidLipThickness - 1,
            lipOuter + 1,
          ),
        );
      }
    } else {
      // Bumps on the lip, sloped below; grooves inside the base's walls they click into.
      for (const [wall, x] of latchSpots) {
        const top = zb + hw;
        lidAdd.push(
          wedge(wall, x, p.latchWidth, [
            [lipOuter - 0.4, top],
            [lipOuter + p.latchDepth, top],
            [lipOuter - 0.4, top - hw - p.latchDepth],
          ]),
        );
        baseHoles.push(
          wallPrism(
            wall,
            roundedRect(p.latchWidth + 2 * tol + 0.4, hw + 2 * tol + p.latchDepth, 0, q),
            x,
            top - (hw + p.latchDepth) / 2,
            -t - 0.5,
            -t + p.latchDepth + tol,
          ),
        );
      }
      if (t - p.latchDepth - tol < 0.8) warnings.push("warn.thinWalls");
    }
  }

  // ---- the lid's opening groove ------------------------------------------------------------------------------
  if (lid && p.hasLidGroove) {
    const name = p.grooveWall === "auto" ? (snap || snapJoint ? latchWalls[0] : "front") : p.grooveWall;
    const wall = walls[name];
    const depth = Math.min(p.grooveDepth, t - 0.4);
    baseHoles.push(
      wallPrism(wall, roundedRect(p.grooveWidth, p.grooveHeight * 2, 0, q), wall.length / 2, H, -depth, 1),
    );
  }

  // ---- wall-mount flanges ------------------------------------------------------------------------------------
  if (p.hasFlanges) {
    for (const name of p.flangeWalls) {
      const wall = walls[name];
      const reach = p.flangeLength;
      const fw = Math.min(p.flangeWidth, wall.length - 2 * p.radius);
      if (fw < 6) {
        warnings.push(`The ${name} wall is too short for a flange.`);
        continue;
      }
      // A tab from inside the wall outward, its far end round, with a hole in that end.
      const end = Math.min(fw / 2, reach);
      const tab = roundedRect(fw, reach + 2 * t, end, q).map(([s, e]) => [s, e + (reach - t) / 2 - t / 2]);
      const origin = onWall(wall, wall.length / 2, 0);
      baseAdd.push(prismIn(tab, origin, wall.u, wall.n, -p.flangeThickness, 0));
      const hole = reach - end;
      const [hx, hy] = [origin[0] + wall.n[0] * hole, origin[1] + wall.n[1] * hole];
      baseHoles.push(cylinder(hx, hy, p.flangeHoleDiameter / 2, -1, p.flangeThickness + 1, q));
      if (p.flangeHoleDiameter > end * 2 - 2) warnings.push("warn.flangeHoles");
    }
  }

  // ---- PCB standoffs -----------------------------------------------------------------------------------------
  if (p.hasPcbStandoffs) {
    const list =
      p.standoffMode === "list"
        ? p.pcbStandoffs
        : [
            [-1, -1],
            [1, -1],
            [-1, 1],
            [1, 1],
          ].map(([sx, sy]) => ({
            x: (sx * p.pcbWidth) / 2,
            y: (sy * p.pcbLength) / 2,
            height: p.pcbStandoffHeight,
            outerDia: p.pcbStandoffOuterDia,
            innerDia: p.pcbStandoffInnerDia,
          }));
    for (const s of list) {
      let [x, y] = [s.x, s.y];
      if (p.pcbRotated) [x, y] = [-y, x];
      x += p.pcbOffsetX;
      y += p.pcbOffsetY;
      const r = s.outerDia / 2;
      if (Math.abs(x) + r > innerW / 2 || Math.abs(y) + r > innerL / 2) {
        warnings.push(`A standoff at ${x.toFixed(1)}, ${y.toFixed(1)} mm is outside the box.`);
        continue;
      }
      const hole = Math.min(s.innerDia, s.outerDia - 1.2) / 2;
      if (p.pcbOnLid && lid) {
        const ringIn = [innerW / 2 - tol - p.lidLipThickness, innerL / 2 - tol - p.lidLipThickness];
        if (lip && (Math.abs(x) + r > ringIn[0] || Math.abs(y) + r > ringIn[1]) && s.height > 0)
          warnings.push("warn.standoffLip");
        lidAdd.push(cylinder(x, y, r, H - s.height, H + 0.5, q));
        lidHoles.push(cylinder(x, y, hole, H - s.height - 1, H + lt - 0.8, q));
      } else {
        inside.push(cylinder(x, y, r, t - 0.5, t + s.height, q));
        baseHoles.push(cylinder(x, y, hole, t + 0.6, t + s.height + 1, q));
      }
    }
  }

  // ---- vents -------------------------------------------------------------------------------------------------
  if (lid && p.hasVentilation) {
    const room = [
      innerW - 2 * (tol + (lip ? p.lidLipThickness : 0)) - 6,
      innerL - 2 * (tol + (lip ? p.lidLipThickness : 0)) - 6,
    ];
    const along = p.ventOrientation === "X" ? 0 : 1;
    const long = Math.min(p.ventSlotLength, room[along]);
    const wide = Math.min(p.ventSlotCount * (p.ventSlotWidth + p.ventSlotSpacing), room[1 - along]);
    if (long < p.ventSlotWidth * 2 || wide < p.ventSlotWidth) warnings.push("warn.noRoomVents");
    else
      for (const outline of ventOutlines(p, long, wide, q))
        lidHoles.push(prism(along === 0 ? outline : rotate2(outline, 90), H - lipH - 1, lidTop + 1));
  }
  for (const name of p.ventWalls) {
    const wall = walls[name];
    const top = H - Math.max(lipH, 0) - 3;
    const bottom = t + 3;
    const roomLong = wall.length - 2 * Math.max(p.radius, p.bossInset + p.bossRadius) - 4;
    const roomTall = top - bottom;
    const horizontal = p.ventOrientation === "X";
    const long = Math.min(p.ventSlotLength, horizontal ? roomLong : roomTall);
    const wide = Math.min(p.ventSlotCount * (p.ventSlotWidth + p.ventSlotSpacing), horizontal ? roomTall : roomLong);
    if (long < p.ventSlotWidth * 2 || wide < p.ventSlotWidth) {
      warnings.push(`The ${name} wall has no room for vents.`);
      continue;
    }
    for (const outline of ventOutlines(p, long, wide, q))
      baseHoles.push(
        wallPrism(wall, horizontal ? outline : rotate2(outline, 90), wall.length / 2, (top + bottom) / 2, -t - 1.5, 1),
      );
  }

  // ---- cutouts and their labels ------------------------------------------------------------------------------
  const labelDepth = (thick) => Math.min(0.6, thick * 0.3);
  for (const c of p.cutouts) {
    const outline = cutoutOutline(c, q);
    const [hx, hz] = cutoutHalf(c);
    const gap = 1.5;
    const labelSpot = (cx, cz) => {
      if (!c.label) return null;
      const size = c.labelSize;
      const { width } = measure(c.label, size);
      if (c.labelPosition === "below") return [cx, cz - hz - gap - size / 2];
      if (c.labelPosition === "left") return [cx - hx - gap - width / 2, cz];
      if (c.labelPosition === "right") return [cx + hx + gap + width / 2, cz];
      return [cx, cz + hz + gap + size / 2];
    };
    if (c.wall === "lid") {
      if (!lid) continue;
      const cx = c.x - W / 2;
      const cy = c.z - L / 2;
      if (Math.abs(cx) + hx > W / 2 - t || Math.abs(cy) + hz > L / 2 - t)
        warnings.push(`A cutout in the lid reaches past its edge.`);
      lidHoles.push(prism(move2(outline, cx, cy), H - lipH - 1, lidTop + 1));
      const spot = labelSpot(cx, cy);
      if (spot)
        lidHoles.push(
          textSolid(c.label, c.labelSize, [spot[0], spot[1], lidTop], [1, 0, 0], [0, 1, 0], -labelDepth(lt), 1),
        );
    } else {
      const wall = walls[c.wall];
      if (c.x - hx < 0 || c.x + hx > wall.length || c.z - hz < 0 || c.z + hz > H)
        warnings.push(`A cutout on the ${c.wall} wall reaches past its edge.`);
      baseHoles.push(wallPrism(wall, outline, c.x, c.z, -t - 1.5, 1));
      const spot = labelSpot(c.x, c.z);
      if (spot)
        baseHoles.push(textSolid(c.label, c.labelSize, onWall(wall, spot[0], spot[1]), wall.u, UP, -labelDepth(t), 1));
    }
  }

  // ---- text --------------------------------------------------------------------------------------------------
  if (p.hasText && p.textString.trim()) {
    const raise = p.textType === "emboss";
    if (p.textPlacement === "lid" && lid && p.hasVentilation) {
      // Both sit in the middle of the lid to begin with.
      const { width: tw, height: th } = measure(p.textString, p.textSize);
      const along = p.ventOrientation === "X";
      const vl = p.ventSlotLength / 2;
      const vw = (p.ventSlotCount * (p.ventSlotWidth + p.ventSlotSpacing)) / 2;
      const [vx, vy] = along ? [vl, vw] : [vw, vl];
      if (Math.abs(p.textOffsetX) < vx + tw / 2 && Math.abs(p.textOffsetY) < vy + th / 2)
        warnings.push("warn.textVents");
    }
    const depth = raise ? p.textDepth : Math.min(p.textDepth, (p.textPlacement === "lid" ? lt : t) - 0.6);
    const [d0, d1] = raise ? [-0.2, depth] : [-depth, 1];
    const { width, height } = measure(p.textString, p.textSize);
    if (p.textPlacement === "lid") {
      if (lid) {
        if (width > W - 2 * p.radius || height > L - 4) warnings.push("warn.textTooBig");
        const solid = textSolid(
          p.textString,
          p.textSize,
          [p.textOffsetX, p.textOffsetY, lidTop],
          [1, 0, 0],
          [0, 1, 0],
          d0,
          d1,
        );
        (raise ? lidAdd : lidHoles).push(solid);
      }
    } else {
      const wall = walls[p.textPlacement];
      if (width > wall.length - 2 * p.radius || height > H - 4)
        warnings.push(`The text is bigger than the ${p.textPlacement} wall.`);
      const solid = textSolid(
        p.textString,
        p.textSize,
        onWall(wall, wall.length / 2 + p.textOffsetX, H / 2 + p.textOffsetY),
        wall.u,
        UP,
        d0,
        d1,
      );
      (raise ? baseAdd : baseHoles).push(solid);
    }
  }

  // ---- putting it together -----------------------------------------------------------------------------------
  const outer = prism(roundedRect(W, L, p.radius, q), 0, H);
  const hollow = subtract(prism(roundedRect(innerW, innerL, innerR, q), t, H + 1), unionAll(inside));
  let base = subtract(union(outer, unionAll(baseAdd)), hollow);
  base = subtract(base, unionAll(baseHoles));

  let lidSolid = [];
  if (lid) {
    lidSolid = prism(roundedRect(W, L, p.radius, q), H, lidTop);
    if (lip) {
      const outerLip = roundedRect(innerW - 2 * tol, innerL - 2 * tol, Math.max(0, innerR - tol), q);
      const innerLip = roundedRect(
        innerW - 2 * (tol + p.lidLipThickness),
        innerL - 2 * (tol + p.lidLipThickness),
        Math.max(0, innerR - tol - p.lidLipThickness),
        q,
      );
      let ring = subtract(prism(outerLip, H - lipH, H + 0.2), prism(innerLip, H - lipH - 1, H + 0.5));
      ring = subtract(ring, unionAll(lipCuts));
      lidSolid = union(lidSolid, ring);
    }
    lidSolid = union(lidSolid, unionAll(lidAdd));
    lidSolid = subtract(lidSolid, unionAll(lidHoles));
  }

  const baseTris = triangles(base);
  const lidTris = lid ? triangles(lidSolid) : [];
  const baseVolume = volume(baseTris) / 1000;
  const lidVolume = volume(lidTris) / 1000;
  return {
    params: p,
    warnings: [...new Set(warnings)],
    base: baseTris,
    lid: lidTris,
    stats: {
      outer: [
        W + (p.hasFlanges ? flangeReach(p, "x") : 0),
        L + (p.hasFlanges ? flangeReach(p, "y") : 0),
        lid ? lidTop : H,
      ],
      inner: [innerW, innerL, H - t],
      baseVolume,
      lidVolume,
      grams: (baseVolume + lidVolume) * PLA,
    },
  };
}

function flangeReach(p, axis) {
  const walls = axis === "x" ? ["left", "right"] : ["front", "back"];
  return walls.filter((w) => p.flangeWalls.includes(w)).length * p.flangeLength;
}

/** The lid turned over to print, its top on the bed. */
export function lidForPrint(tris) {
  if (!tris.length) return tris;
  let top = -Infinity;
  for (const tri of tris) for (const v of tri) top = Math.max(top, v[2]);
  // Half a turn about x: y and z change sign, which is a turn, not a mirror, so the triangles keep their winding.
  return tris.map((tri) => tri.map(([x, y, z]) => [x, -y, top - z]));
}

// ---- viewer.js ----

// The 3D view: the base and the lid drawn with WebGL, each in its colour, on a grid of the floor, turned by dragging
// and zoomed by the wheel. Drawn when something changes rather than every frame, and with no 3D library.

const VERTEX = `
attribute vec3 position;
attribute vec3 normal;
uniform mat4 viewProjection;
uniform vec3 offset;
uniform vec3 colour;
uniform float lit;
varying vec3 shaded;
void main() {
  vec3 light = normalize(vec3(-0.45, -0.6, 0.75));
  float key = abs(dot(normal, light));
  float rim = max(dot(normal, normalize(vec3(0.6, 0.5, 0.2))), 0.0);
  shaded = mix(colour, colour * (0.42 + 0.5 * key + 0.14 * rim), lit);
  gl_Position = viewProjection * vec4(position + offset, 1.0);
}`;

const FRAGMENT = `
precision mediump float;
varying vec3 shaded;
uniform float alpha;
void main() {
  gl_FragColor = vec4(min(shaded, vec3(1.0)) * alpha, alpha);
}`;

export const DEFAULT_ORBIT = { azimuth: -58, elevation: 30, zoom: 1 };

function perspective(fovy, aspect, near, far) {
  const f = 1 / Math.tan(fovy / 2);
  const range = 1 / (near - far);
  return [f / aspect, 0, 0, 0, 0, f, 0, 0, 0, 0, (far + near) * range, -1, 0, 0, 2 * far * near * range, 0];
}

function lookAt(eye, target, up) {
  const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  const norm = (v) => {
    const l = Math.hypot(v[0], v[1], v[2]) || 1;
    return [v[0] / l, v[1] / l, v[2] / l];
  };
  const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
  const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const z = norm(sub(eye, target));
  const x = norm(cross(up, z));
  const y = cross(z, x);
  return [x[0], y[0], z[0], 0, x[1], y[1], z[1], 0, x[2], y[2], z[2], 0, -dot(x, eye), -dot(y, eye), -dot(z, eye), 1];
}

function multiply(a, b) {
  const out = new Array(16);
  for (let col = 0; col < 4; col++)
    for (let row = 0; row < 4; row++) {
      let sum = 0;
      for (let k = 0; k < 4; k++) sum += a[k * 4 + row] * b[col * 4 + k];
      out[col * 4 + row] = sum;
    }
  return out;
}

/** Triangles as flat arrays: positions, and each triangle's normal for its three corners. */
function flatten(tris) {
  const positions = new Float32Array(tris.length * 9);
  const normals = new Float32Array(tris.length * 9);
  tris.forEach(([a, b, c], t) => {
    const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    const v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    const n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    const length = Math.hypot(n[0], n[1], n[2]) || 1;
    [a, b, c].forEach((p, k) => {
      positions.set(p, t * 9 + k * 3);
      normals.set([n[0] / length, n[1] / length, n[2] / length], t * 9 + k * 3);
    });
  });
  return { positions, normals, count: tris.length * 3 };
}

const hexToRgb = (hex) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return [0.5, 0.5, 0.5];
  return [0, 2, 4].map((i) => parseInt(m[1].slice(i, i + 2), 16) / 255);
};

/**
 * A view on `canvas`, or null where the browser has no WebGL. Show parts with `show({ name: { tris, colour,
 * offset } })`; drag to turn, wheel to zoom, double-click to start again, and arrow keys, + and − when it has focus.
 */
export function createViewer(canvas, { grid = "#888888" } = {}) {
  const gl = canvas.getContext("webgl", {
    antialias: true,
    alpha: true,
    premultipliedAlpha: true,
    preserveDrawingBuffer: true,
  });
  if (!gl) return null;
  const compile = (type, source) => {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS))
      throw new Error(gl.getShaderInfoLog(shader) || "Shader failed");
    return shader;
  };
  const program = gl.createProgram();
  gl.attachShader(program, compile(gl.VERTEX_SHADER, VERTEX));
  gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAGMENT));
  gl.linkProgram(program);
  const at = {
    position: gl.getAttribLocation(program, "position"),
    normal: gl.getAttribLocation(program, "normal"),
    viewProjection: gl.getUniformLocation(program, "viewProjection"),
    offset: gl.getUniformLocation(program, "offset"),
    colour: gl.getUniformLocation(program, "colour"),
    lit: gl.getUniformLocation(program, "lit"),
    alpha: gl.getUniformLocation(program, "alpha"),
  };

  const parts = new Map();
  let gridLines = null;
  let gridColour = hexToRgb(grid);
  let bounds = { centre: [0, 0, 20], radius: 60 };
  const orbit = { ...DEFAULT_ORBIT };
  let frame = 0;

  const upload = (data) => {
    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
    return buffer;
  };

  function draw() {
    frame = 0;
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    const width = Math.max(1, Math.round(canvas.clientWidth * ratio));
    const height = Math.max(1, Math.round(canvas.clientHeight * ratio));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    gl.viewport(0, 0, width, height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    const { centre, radius } = bounds;
    const a = (orbit.azimuth * Math.PI) / 180;
    const e = (orbit.elevation * Math.PI) / 180;
    const fov = (30 * Math.PI) / 180;
    const distance = (radius / Math.sin(fov / 2)) * 1.05 * orbit.zoom;
    const eye = [
      centre[0] + distance * Math.cos(e) * Math.cos(a),
      centre[1] + distance * Math.cos(e) * Math.sin(a),
      centre[2] + distance * Math.sin(e),
    ];
    const matrix = multiply(
      perspective(fov, width / height, Math.max(distance / 50, distance - radius * 3), distance + radius * 4),
      lookAt(eye, centre, [0, 0, 1]),
    );
    gl.useProgram(program);
    gl.enable(gl.DEPTH_TEST);
    gl.uniformMatrix4fv(at.viewProjection, false, new Float32Array(matrix));
    gl.enableVertexAttribArray(at.position);

    if (gridLines) {
      gl.disableVertexAttribArray(at.normal);
      gl.vertexAttrib3f(at.normal, 0, 0, 1);
      gl.bindBuffer(gl.ARRAY_BUFFER, gridLines.buffer);
      gl.vertexAttribPointer(at.position, 3, gl.FLOAT, false, 0, 0);
      gl.uniform3f(at.offset, 0, 0, 0);
      gl.uniform3fv(at.colour, gridColour);
      gl.uniform1f(at.lit, 0);
      gl.uniform1f(at.alpha, 0.45);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.drawArrays(gl.LINES, 0, gridLines.count);
      gl.disable(gl.BLEND);
    }
    gl.enableVertexAttribArray(at.normal);
    for (const part of parts.values()) {
      if (!part.visible || !part.count) continue;
      gl.bindBuffer(gl.ARRAY_BUFFER, part.positions);
      gl.vertexAttribPointer(at.position, 3, gl.FLOAT, false, 0, 0);
      gl.bindBuffer(gl.ARRAY_BUFFER, part.normals);
      gl.vertexAttribPointer(at.normal, 3, gl.FLOAT, false, 0, 0);
      gl.uniform3fv(at.offset, part.offset);
      gl.uniform3fv(at.colour, part.colour);
      gl.uniform1f(at.lit, 1);
      gl.uniform1f(at.alpha, 1);
      gl.drawArrays(gl.TRIANGLES, 0, part.count);
    }
  }
  const redraw = () => {
    if (!frame) frame = requestAnimationFrame(draw);
  };

  /** A grid of 10 mm squares on the floor, a little bigger than the model. */
  function makeGrid(min, max) {
    const step = 10;
    const pad = 20;
    const x0 = Math.floor((min[0] - pad) / step) * step;
    const x1 = Math.ceil((max[0] + pad) / step) * step;
    const y0 = Math.floor((min[1] - pad) / step) * step;
    const y1 = Math.ceil((max[1] + pad) / step) * step;
    const lines = [];
    for (let x = x0; x <= x1; x += step) lines.push(x, y0, -0.05, x, y1, -0.05);
    for (let y = y0; y <= y1; y += step) lines.push(x0, y, -0.05, x1, y, -0.05);
    if (gridLines) gl.deleteBuffer(gridLines.buffer);
    gridLines = { buffer: upload(new Float32Array(lines)), count: lines.length / 3 };
  }

  // Turning and zooming.
  const turn = (dAzimuth, dElevation) => {
    orbit.azimuth = (orbit.azimuth + dAzimuth) % 360;
    orbit.elevation = Math.max(-85, Math.min(89, orbit.elevation + dElevation));
    redraw();
  };
  const zoom = (factor) => {
    orbit.zoom = Math.max(0.2, Math.min(5, orbit.zoom * factor));
    redraw();
  };
  const reset = () => {
    Object.assign(orbit, DEFAULT_ORBIT);
    redraw();
  };
  let last = null;
  const down = (event) => {
    if (event.button !== 0) return;
    canvas.setPointerCapture(event.pointerId);
    last = { x: event.clientX, y: event.clientY };
    canvas.style.cursor = "grabbing";
  };
  const move = (event) => {
    if (!last) return;
    turn(-(event.clientX - last.x) * 0.5, (event.clientY - last.y) * 0.4);
    last = { x: event.clientX, y: event.clientY };
  };
  const up = () => {
    last = null;
    canvas.style.cursor = "";
  };
  const wheel = (event) => {
    event.preventDefault();
    zoom(event.deltaY > 0 ? 1.1 : 1 / 1.1);
  };
  const key = (event) => {
    const steps = { ArrowLeft: [10, 0], ArrowRight: [-10, 0], ArrowUp: [0, -8], ArrowDown: [0, 8] };
    if (steps[event.key]) turn(...steps[event.key]);
    else if (event.key === "+" || event.key === "=") zoom(1 / 1.1);
    else if (event.key === "-" || event.key === "_") zoom(1.1);
    else if (event.key === "0" || event.key === "Home") reset();
    else return;
    event.preventDefault();
    event.stopPropagation();
  };
  const listeners = [
    ["pointerdown", down],
    ["pointermove", move],
    ["pointerup", up],
    ["pointercancel", up],
    ["dblclick", reset],
    ["keydown", key],
  ];
  for (const [type, fn] of listeners) canvas.addEventListener(type, fn);
  canvas.addEventListener("wheel", wheel, { passive: false });
  const resize = new ResizeObserver(redraw);
  resize.observe(canvas);

  return {
    /** Replaces the parts drawn: { name: { tris, colour: "#rrggbb", offset: [x, y, z], visible } }. */
    show(next, { refit = false } = {}) {
      for (const [name, part] of parts)
        if (!(name in next)) {
          gl.deleteBuffer(part.positions);
          gl.deleteBuffer(part.normals);
          parts.delete(name);
        }
      const min = [Infinity, Infinity, Infinity];
      const max = [-Infinity, -Infinity, -Infinity];
      for (const [name, spec] of Object.entries(next)) {
        let part = parts.get(name);
        if (!part || part.tris !== spec.tris) {
          if (part) {
            gl.deleteBuffer(part.positions);
            gl.deleteBuffer(part.normals);
          }
          const flat = flatten(spec.tris);
          part = {
            tris: spec.tris,
            positions: upload(flat.positions),
            normals: upload(flat.normals),
            count: flat.count,
          };
          parts.set(name, part);
        }
        part.colour = hexToRgb(spec.colour);
        part.offset = spec.offset ?? [0, 0, 0];
        part.visible = spec.visible !== false;
        if (!part.visible) continue;
        for (const tri of spec.tris)
          for (const p of tri)
            for (let i = 0; i < 3; i++) {
              const v = p[i] + part.offset[i];
              if (v < min[i]) min[i] = v;
              if (v > max[i]) max[i] = v;
            }
      }
      if (Number.isFinite(min[0])) {
        const centre = min.map((m, i) => (m + max[i]) / 2);
        const radius = Math.max(10, Math.hypot(max[0] - min[0], max[1] - min[1], max[2] - min[2]) / 2);
        // Kept steady while the model changes a little, so the view doesn't jump at every setting.
        if (
          refit ||
          Math.abs(radius - bounds.radius) > bounds.radius * 0.25 ||
          Math.hypot(...centre.map((c, i) => c - bounds.centre[i])) > bounds.radius * 0.3
        )
          bounds = { centre, radius };
        makeGrid(min, max);
      }
      redraw();
    },
    setGridColour(hex) {
      gridColour = hexToRgb(hex);
      redraw();
    },
    reset,
    redraw,
    /** The view as a PNG, `size` pixels square on `background`, for a model's picture. */
    async snapshot(size = 900, background = "#ffffff") {
      draw();
      const out = document.createElement("canvas");
      out.width = size;
      out.height = size;
      const ctx = out.getContext("2d");
      ctx.fillStyle = background;
      ctx.fillRect(0, 0, size, size);
      const side = Math.min(canvas.width, canvas.height);
      ctx.drawImage(canvas, (canvas.width - side) / 2, (canvas.height - side) / 2, side, side, 0, 0, size, size);
      return new Promise((resolve) => out.toBlob((blob) => resolve(blob), "image/png"));
    },
    dispose() {
      cancelAnimationFrame(frame);
      resize.disconnect();
      for (const [type, fn] of listeners) canvas.removeEventListener(type, fn);
      canvas.removeEventListener("wheel", wheel);
      for (const part of parts.values()) {
        gl.deleteBuffer(part.positions);
        gl.deleteBuffer(part.normals);
      }
      if (gridLines) gl.deleteBuffer(gridLines.buffer);
      gl.deleteProgram(program);
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    },
  };
}

// ---- ui.js ----

// The tool's window: the settings in tabs, the enclosure in 3D, rebuilt as they change, and projects kept for the
// user to open again, as well as models saved to Thingport and files downloaded.


const svg = (paths) =>
  `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const ICONS = {
  more: svg('<circle cx="12" cy="5" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="12" cy="19" r="1.4"/>'),
  open: svg('<path d="M4 5a1 1 0 0 1 1-1h4l2 2h8a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1z"/>'),
  copy: svg(
    '<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h3"/>',
  ),
  json: svg(
    '<path d="M8 4H7a2 2 0 0 0-2 2v4l-2 2 2 2v4a2 2 0 0 0 2 2h1M16 4h1a2 2 0 0 1 2 2v4l2 2-2 2v4a2 2 0 0 1-2 2h-1"/>',
  ),
  remove: svg('<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>'),
  close: svg('<path d="M6 6l12 12M18 6 6 18"/>'),
  add: svg('<path d="M12 5v14M5 12h14"/>'),
  edit: svg('<path d="M4 20h4L19 9l-4-4L4 16z"/>'),
  box: svg('<path d="M12 3 20 7.5v9L12 21l-8-4.5v-9z"/><path d="M12 12l8-4.5M12 12v9M12 12 4 7.5"/>'),
  stl: svg('<path d="M12 3v12m0 0-4-4m4 4 4-4M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2"/>'),
};

const COLOURS = [
  ["colour.accent", null],
  ["colour.graphite", "#3b3f45"],
  ["colour.white", "#e9e7e1"],
  ["colour.orange", "#f07f19"],
  ["colour.navy", "#23395b"],
  ["colour.red", "#cf3f45"],
];
const WALL_NAMES = { front: "side.front", back: "side.back", left: "side.left", right: "side.right", lid: "part.lid" };
const SHAPES = [
  ["rect", "shape.rectangle"],
  ["circle", "shape.circle"],
  ["type-c", "shape.roundedSlot"],
  ["dsub", "D-sub"],
];
const TABS = [
  ["shell", "shell.title"],
  ["lid", "part.lid"],
  ["pcb", "pcb.title"],
  ["ports", "cutout.ports"],
  ["vents", "vent.vents"],
  ["text", "text.title"],
];
const UNTITLED = "projects.untitled";
const BUILD_DELAY_MS = 180;
const SAVE_DRAFT_MS = 600;

const round = (value, places = 1) => Number(Number(value).toFixed(places));
const fmt = (value) => `${round(value)}`.replace(/\.0$/, "");
const slugOf = (text) =>
  String(text)
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "") || "enclosure";

function escapeHtml(text) {
  return String(text ?? "").replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );
}

/** Two colours mixed, `t` of the second. */
function mix(a, b, t) {
  const parse = (hex) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
    return m ? [0, 2, 4].map((i) => parseInt(m[1].slice(i, i + 2), 16)) : [128, 128, 128];
  };
  const [x, y] = [parse(a), parse(b)];
  return `#${x
    .map((c, i) =>
      Math.round(c + (y[i] - c) * t)
        .toString(16)
        .padStart(2, "0"),
    )
    .join("")}`;
}

/** "3 h ago" and the like. */
function ago(time, t) {
  const s = Math.max(0, (Date.now() - new Date(time).getTime()) / 1000);
  if (s < 60) return t("time.justNow");
  if (s < 3600) return t("time.minutesAgo", { minutes: Math.round(s / 60) });
  if (s < 86400) return t("time.hoursAgo", { hours: Math.round(s / 3600) });
  return new Date(time).toLocaleDateString();
}

const el = (tag, props = {}, ...children) => {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null || value === false) continue;
    if (key === "class") node.className = value;
    else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
    else if (key === "html") node.innerHTML = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat()) if (child != null && child !== false) node.append(child);
  return node;
};

export default async function mount(thingport) {
  const { root, theme, storage, models, ui, t, labels } = thingport;
  const shell = root.querySelector(".enc");
  const $ = (id) => root.querySelector(`#enc-${id}`);
  const colours = {
    bg: theme.background,
    panel: theme.paper,
    divider: theme.divider,
    text: theme.text,
    muted: theme.textSecondary,
    accent: theme.primary,
    // What reads on the accent, which Thingport picks per accent colour: white for most, dark for the light ones
    // like amber. The fallback keeps an older Thingport, which didn't hand it over, close to right.
    "accent-ink": theme.primaryContrast ?? "#ffffff",
    danger: theme.error,
    warning: theme.warning ?? theme.error,
    font: theme.fontFamily,
  };
  for (const [name, value] of Object.entries(colours)) shell.style.setProperty(`--${name}`, value);

  // ---- state -------------------------------------------------------------------------------------------------
  let params = structuredClone(DEFAULTS);
  let name = UNTITLED;
  let projectId = null;
  let saved = null; // { name, params } as last saved or opened, to tell whether there's anything to save
  // The lid lifted a little to start with, so what's inside shows.
  const view = { show: "both", explode: 24, colour: 0, quality: "normal", tab: "shell" };
  let model = null;
  let closed = false;
  try {
    const draft = await storage.get("draft");
    if (draft && typeof draft === "object" && draft.params) {
      params = normalize(draft.params).params;
      name = String(draft.name || UNTITLED);
      projectId = draft.projectId ?? null;
      // Compared as the settings are once filled in, as they're loaded.
      saved = draft.saved?.params
        ? { name: String(draft.saved.name), params: normalize(draft.saved.params).params }
        : null;
      Object.assign(view, draft.view ?? {});
    }
  } catch {
    // Starts afresh.
  }
  const stateJson = () => JSON.stringify({ name, params });
  // A design not yet touched has nothing to save.
  if (
    !saved &&
    !projectId &&
    JSON.stringify(params) === JSON.stringify(normalize(DEFAULTS).params) &&
    name === UNTITLED
  )
    saved = JSON.parse(stateJson());
  const dirty = () => !saved || JSON.stringify(saved) !== stateJson();

  let draftTimer = 0;
  const persist = () => {
    clearTimeout(draftTimer);
    draftTimer = setTimeout(
      () => void storage.set("draft", { name, params, projectId, saved, view }).catch(() => undefined),
      SAVE_DRAFT_MS,
    );
  };

  // ---- undo --------------------------------------------------------------------------------------------------
  const past = [];
  const future = [];
  let lastMark = 0;
  /** Remembers the settings before a change; changes close together are undone together. */
  const remember = () => {
    const now = Date.now();
    if (now - lastMark > 700) {
      past.push(JSON.stringify(params));
      if (past.length > 100) past.shift();
      future.length = 0;
    }
    lastMark = now;
  };
  const undo = () => {
    if (!past.length) return;
    future.push(JSON.stringify(params));
    params = JSON.parse(past.pop());
    lastMark = 0;
    afterChange(true);
  };
  const redo = () => {
    if (!future.length) return;
    past.push(JSON.stringify(params));
    params = JSON.parse(future.pop());
    lastMark = 0;
    afterChange(true);
  };

  function set(key, value, rerender = false) {
    remember();
    params = { ...params, [key]: value };
    afterChange(rerender);
  }
  function afterChange(rerender) {
    persist();
    updateBar();
    scheduleBuild();
    if (rerender) renderForm();
  }

  // ---- building ----------------------------------------------------------------------------------------------
  let buildTimer = 0;
  let building = null;
  let busyTimer = 0;
  const scheduleBuild = () => {
    clearTimeout(buildTimer);
    buildTimer = setTimeout(() => void build(), BUILD_DELAY_MS);
  };
  /** Builds the enclosure from the settings as they are, and shows it. */
  function build() {
    clearTimeout(buildTimer);
    buildTimer = 0;
    building = new Promise((resolve) => {
      clearTimeout(busyTimer);
      busyTimer = setTimeout(() => ($("building").hidden = false), 120);
      // A frame first, so t("status.building") shows before the work holds the page.
      requestAnimationFrame(() =>
        setTimeout(() => {
          if (closed) return resolve();
          try {
            model = buildEnclosure(params, { quality: view.quality });
          } catch (err) {
            model = {
              ...(model ?? { base: [], lid: [], stats: null }),
              warnings: [t("warn.buildFailed", { error: err?.message || err })],
            };
          }
          clearTimeout(busyTimer);
          $("building").hidden = true;
          showModel();
          resolve();
        }, 0),
      );
    });
    return building;
  }
  const ready = async () => {
    if (buildTimer) {
      clearTimeout(buildTimer);
      buildTimer = 0;
      await build();
    } else if (building) await building;
  };

  // ---- the view ----------------------------------------------------------------------------------------------
  const canvas = $("canvas");
  let viewer = null;
  try {
    viewer = createViewer(canvas, { grid: theme.textSecondary });
  } catch {
    viewer = null;
  }
  if (!viewer) $("view").append(el("div", { class: "enc-novw" }, t("view.noWebgl")));

  const baseColour = () => COLOURS[view.colour]?.[1] ?? theme.primary;
  const lidColour = () => mix(baseColour(), theme.mode === "dark" ? "#000000" : "#ffffff", 0.22);
  let firstShow = true;
  function showModel() {
    if (!model) return;
    const hasLid = model.lid.length > 0;
    const lift = hasLid ? view.explode : 0;
    viewer?.show(
      {
        base: { tris: model.base, colour: baseColour(), visible: view.show !== "lid" },
        lid: { tris: model.lid, colour: lidColour(), offset: [0, 0, lift], visible: hasLid && view.show !== "base" },
      },
      { refit: firstShow },
    );
    firstShow = false;
    const s = model.stats;
    if (s) {
      $("size").innerHTML = `<b>${s.outer.map(fmt).join(" × ")}</b><span>mm</span>`;
      $("size").title = `Outside, with the lid. Inside: ${s.inner.map(fmt).join(" × ")} mm.`;
      $("weight").innerHTML = `<b>≈ ${Math.round(s.grams)} g</b><span>PLA</span>`;
      $("weight").title =
        `Base ${fmt(s.baseVolume)} cm³${hasLid ? `, lid ${fmt(s.lidVolume)} cm³` : ""}, printed solid.`;
    }
    updateBar();
    const warnings = model.warnings ?? [];
    const button = $("warnings");
    button.hidden = !warnings.length;
    button.textContent = t(warnings.length === 1 ? "notes.one" : "notes.many", { count: warnings.length });
    const list = $("warningList");
    list.replaceChildren(...warnings.map((w) => el("li", {}, t(w))));
    if (!warnings.length) {
      list.hidden = true;
      button.setAttribute("aria-expanded", "false");
    }
  }
  $("warnings").addEventListener("click", () => {
    const list = $("warningList");
    list.hidden = !list.hidden;
    $("warnings").setAttribute("aria-expanded", String(!list.hidden));
  });

  // View controls.
  function renderViewControls() {
    const segment = (container, options, value, onPick) =>
      container.replaceChildren(
        ...options.map(([v, label]) =>
          el("button", { type: "button", "aria-pressed": String(v === value), onclick: () => onPick(v) }, label),
        ),
      );
    segment(
      $("show"),
      [
        ["both", t("opt.both")],
        ["base", t("part.base")],
        ["lid", t("part.lid")],
      ],
      view.show,
      (v) => {
        view.show = v;
        renderViewControls();
        showModel();
        persist();
      },
    );
    segment(
      $("quality"),
      [
        ["draft", t("detail.draft")],
        ["normal", t("detail.normal")],
        ["high", t("detail.fine")],
      ],
      view.quality,
      (v) => {
        view.quality = v;
        renderViewControls();
        persist();
        void build();
      },
    );
    $("quality").title = t("detail.help");
    $("swatches").replaceChildren(
      ...COLOURS.map(([label, hex], i) =>
        el("button", {
          type: "button",
          title: t(label),
          "aria-label": t(label),
          "aria-pressed": String(i === view.colour),
          style: `background:${hex ?? theme.primary}`,
          onclick: () => {
            view.colour = i;
            renderViewControls();
            showModel();
            persist();
          },
        }),
      ),
    );
    $("explode").value = String(view.explode);
  }
  $("explode").addEventListener("input", (event) => {
    view.explode = Number(event.target.value);
    showModel();
    persist();
  });
  $("resetView").addEventListener("click", () => viewer?.reset());

  // ---- the settings form -------------------------------------------------------------------------------------
  const help = (text) =>
    el("span", { class: "enc-help", title: text, "aria-label": text, role: "img", tabindex: "0" }, "?");

  function numberField(key, label, { unit = "mm", range = key, value, onValue, title } = {}) {
    const [min, max, step] = RANGES[range] ?? [-1000, 1000, 0.1];
    const current = value ?? params[key];
    const input = el("input", {
      type: "number",
      min,
      max,
      step,
      value: String(current),
      "aria-label": label,
      inputmode: "decimal",
    });
    input.addEventListener("input", () => {
      const v = Number(input.value);
      if (input.value === "" || !Number.isFinite(v)) return;
      if (onValue) onValue(v);
      else set(key, v);
    });
    input.addEventListener("change", () => {
      if (input.value === "" || !Number.isFinite(Number(input.value))) input.value = String(current);
    });
    return el(
      "label",
      { class: "enc-field", title },
      el("span", {}, label),
      el("div", { class: "enc-input" }, input, unit ? el("span", { class: "enc-unit" }, unit) : null),
    );
  }
  const grid = (n, ...fields) => el("div", { class: "enc-grid", style: `--n:${n}` }, ...fields);

  function toggle(key, label, { title } = {}) {
    const input = el("input", { type: "checkbox", role: "switch" });
    input.checked = Boolean(params[key]);
    input.addEventListener("change", () => set(key, input.checked, true));
    return el(
      "label",
      { class: "enc-switch", title },
      input,
      el("span", { class: "enc-track", "aria-hidden": "true" }),
      el("b", {}, label),
    );
  }

  function segmented(label, options, value, onPick) {
    return el(
      "div",
      { class: "enc-field" },
      label ? el("span", {}, label) : null,
      el(
        "div",
        { class: "enc-seg", role: "group", "aria-label": label || undefined },
        options.map(([v, text, title]) =>
          el("button", { type: "button", "aria-pressed": String(v === value), title, onclick: () => onPick(v) }, text),
        ),
      ),
    );
  }
  const seg = (key, label, options) => segmented(label, options, params[key], (v) => set(key, v, true));

  function chips(key, label, options) {
    const value = params[key] ?? [];
    return el(
      "div",
      { class: "enc-field" },
      el("span", {}, label),
      el(
        "div",
        { class: "enc-chips", role: "group", "aria-label": label },
        options.map(([v, text]) =>
          el(
            "button",
            {
              type: "button",
              "aria-pressed": String(value.includes(v)),
              onclick: () => set(key, value.includes(v) ? value.filter((x) => x !== v) : [...value, v], true),
            },
            text,
          ),
        ),
      ),
    );
  }

  const section = (title, { tip, toggleKey, action } = {}, ...children) =>
    el(
      "section",
      { class: "enc-section" },
      el(
        "div",
        { class: "enc-section-head" },
        toggleKey ? toggle(toggleKey, title) : el("h3", {}, title),
        tip ? help(tip) : null,
        el("span", { class: "enc-spacer" }),
        action ?? null,
      ),
      ...(toggleKey && !params[toggleKey] ? [] : children),
    );

  const wallOptions = Object.entries(WALL_NAMES)
    .filter(([w]) => w !== "lid")
    .map(([id, label]) => [id, t(label)]);

  const TAB_CONTENT = {
    shell: () => [
      section(
        t("shell.sizeOutside"),
        { tip: t("shell.sizeHelp") },
        grid(
          3,
          numberField("width", t("dim.width")),
          numberField("length", t("dim.length")),
          numberField("height", t("dim.height")),
        ),
        grid(
          3,
          numberField("thickness", t("part.walls"), { title: "1.6 to 4 mm prints well" }),
          numberField("radius", t("shell.corners")),
          numberField("tolerance", t("lid.fit"), { title: t("lid.fitHelp") }),
        ),
      ),
      section(
        t("flange.title"),
        {
          toggleKey: "hasFlanges",
          tip: t("flange.help"),
        },
        chips("flangeWalls", "On", wallOptions),
        grid(
          2,
          numberField("flangeLength", t("screw.reach")),
          numberField("flangeWidth", t("dim.width")),
          numberField("flangeHoleDiameter", t("screw.hole")),
          numberField("flangeThickness", t("dim.thickness")),
        ),
      ),
    ],
    lid: () => [
      section(
        t("part.lid"),
        { toggleKey: "hasLid", tip: "A separate lid, printed upside down." },
        seg("lidType", t("shell.profile"), [
          ["flat", t("lid.flat"), "A plate sitting on top"],
          ["lip", t("lid.withLip"), "A lip drops inside the base and keeps it in place"],
        ]),
        params.lidType === "lip"
          ? grid(
              3,
              numberField("lidThickness", t("dim.thickness")),
              numberField("lidLipHeight", t("lid.lipHeight")),
              numberField("lidLipThickness", t("lid.lipWall")),
            )
          : grid(3, numberField("lidThickness", t("dim.thickness"))),
      ),
      params.hasLid
        ? section(
            t("flange.fixing"),
            { tip: t("join.help") },
            seg("lidFixation", "", [
              ["screws", t("join.screws")],
              ["snap", t("snap.title"), t("snap.hooksHelp")],
              ["snapJoint", t("join.snap"), t("snap.bumpsHelp")],
            ]),
            ...(params.lidFixation === "screws"
              ? [
                  toggle("hasCornerScrews", t("screw.cornerBosses")),
                  params.hasCornerScrews
                    ? grid(
                        3,
                        numberField("screwDiameter", t("screw.baseHole"), {
                          title: t("screw.pilotHelp"),
                        }),
                        numberField("lidScrewDiameter", t("screw.lidHole")),
                        numberField("screwHeadDiameter", t("screw.head")),
                        numberField("screwHeadDepth", t("screw.headSinks")),
                        numberField("bossRadius", t("screw.bossRadius")),
                        numberField("bossInset", t("vent.inset"), { title: t("screw.reachHelp") }),
                      )
                    : null,
                ]
              : [
                  grid(
                    2,
                    numberField("latchWidth", t("dim.width")),
                    numberField("latchDepth", t("snap.catch")),
                    numberField("latchHeight", t("dim.height")),
                    numberField("latchCount", t("vent.perWall"), { unit: "" }),
                  ),
                  chips("latchWalls", "On", wallOptions),
                ]),
          )
        : null,
      params.hasLid
        ? section(
            t("snap.openingGroove"),
            { toggleKey: "hasLidGroove", tip: "A notch at the top of a wall, for a flat tool to lift the lid." },
            seg("grooveWall", t("part.wall"), [["auto", t("opt.auto")], ...wallOptions]),
            grid(
              3,
              numberField("grooveWidth", t("dim.width")),
              numberField("grooveHeight", t("dim.height")),
              numberField("grooveDepth", t("dim.depth")),
            ),
          )
        : null,
    ],
    pcb: () => [
      section(
        t("pcb.standoffs"),
        { toggleKey: "hasPcbStandoffs", tip: t("pcb.help") },
        boardPicker(),
        grid(
          2,
          segmented(
            t("pcb.mountedOn"),
            [
              [false, t("part.base")],
              [true, t("part.lid")],
            ],
            params.pcbOnLid,
            (v) => set("pcbOnLid", v, true),
          ),
          el("div", { class: "enc-field" }, el("span", {}, " "), toggle("pcbRotated", t("pcb.turned90"))),
        ),
        seg("standoffMode", t("vent.holes"), [
          ["grid", "4 corners"],
          ["list", t("vent.eachOne")],
        ]),
        ...(params.standoffMode === "grid"
          ? [
              grid(
                3,
                numberField("pcbWidth", t("dir.across")),
                numberField("pcbLength", t("dir.along")),
                numberField("pcbStandoffHeight", t("dim.height")),
                numberField("pcbStandoffOuterDia", t("pcb.postDia")),
                numberField("pcbStandoffInnerDia", t("screw.holeDia")),
              ),
            ]
          : [standoffList()]),
        grid(2, numberField("pcbOffsetX", t("cutout.moveX")), numberField("pcbOffsetY", t("cutout.moveY"))),
      ),
    ],
    ports: () => [
      section(
        t("cutout.title"),
        {
          tip: t("cutout.help"),
          action: el(
            "button",
            { class: "enc-btn enc-small", type: "button", onclick: addCutout },
            el("span", { html: ICONS.add }),
            t("act.add"),
          ),
        },
        cutoutList(),
      ),
    ],
    vents: () => [
      section(
        t("vent.vents"),
        { tip: t("vent.help") },
        toggle("hasVentilation", t("place.inLid")),
        chips("ventWalls", t("place.inWalls"), wallOptions),
        ...(params.hasVentilation || params.ventWalls.length
          ? [
              seg("ventPattern", t("vent.pattern"), [
                ["slots", t("vent.slots")],
                ["honeycomb", t("vent.honeycomb")],
                ["dots", t("vent.dots")],
                ["diamonds", t("vent.diamonds")],
              ]),
              seg("ventOrientation", t("vent.running"), [
                ["X", t("dir.alongX"), t("place.acrossHelp")],
                ["Y", t("dir.alongY"), t("place.alongHelp")],
              ]),
              grid(
                2,
                numberField("ventSlotCount", params.ventPattern === "slots" ? t("vent.slots") : t("vent.rowsUpTo"), {
                  unit: "",
                }),
                numberField("ventSlotLength", t("dim.length")),
                numberField(
                  "ventSlotWidth",
                  params.ventPattern === "slots" ? t("vent.slotWidth") : t("screw.holeSize"),
                ),
                numberField("ventSlotSpacing", t("vent.gap")),
              ),
            ]
          : []),
      ),
    ],
    text: () => [
      section(
        t("text.title"),
        {
          toggleKey: "hasText",
          tip: t("text.help"),
        },
        textInput("textString", t("text.title")),
        seg("textPlacement", "On", [["lid", t("part.lid")], ...wallOptions]),
        seg("textType", t("text.style"), [
          ["deboss", t("text.cutIn")],
          ["emboss", t("text.raised")],
        ]),
        grid(
          2,
          numberField("textSize", t("dim.size")),
          numberField("textDepth", t("dim.depth")),
          numberField("textOffsetX", t("cutout.moveX")),
          numberField("textOffsetY", t("cutout.moveY")),
        ),
      ),
    ],
  };

  function textInput(key, label, { value, onValue, maxlength = 40, placeholder } = {}) {
    const input = el("input", {
      class: "enc-text",
      value: value ?? params[key] ?? "",
      maxlength,
      "aria-label": label,
      placeholder,
      autocomplete: "off",
    });
    input.addEventListener("input", () => (onValue ? onValue(input.value) : set(key, input.value)));
    return el("label", { class: "enc-field" }, el("span", {}, label), input);
  }

  function boardPicker() {
    const select = el(
      "select",
      { "aria-label": t("pcb.board") },
      el("option", { value: "none" }, t("opt.custom")),
      BOARDS.map((b) => el("option", { value: b.id }, b.name)),
    );
    select.value = BOARDS.some((b) => b.id === params.pcbPreset) ? params.pcbPreset : "none";
    select.addEventListener("change", () => {
      const board = BOARDS.find((b) => b.id === select.value);
      remember();
      if (!board) params = { ...params, pcbPreset: "none" };
      else
        params = {
          ...params,
          pcbPreset: board.id,
          standoffMode: "list",
          pcbStandoffs: board.holes.map(([x, y], i) => ({
            id: `s${i + 1}`,
            x,
            y,
            height: board.height,
            outerDia: board.outerDia,
            innerDia: board.innerDia,
          })),
        };
      afterChange(true);
    });
    return el(
      "label",
      { class: "enc-field" },
      el("span", {}, t("pcb.board")),
      el("div", { class: "enc-input" }, select),
    );
  }

  function standoffList() {
    const list = params.pcbStandoffs;
    const update = (i, field, v) => {
      remember();
      params = { ...params, pcbPreset: "none", pcbStandoffs: list.map((s, j) => (j === i ? { ...s, [field]: v } : s)) };
      afterChange(false);
    };
    const rows = list.map((s, i) =>
      el(
        "div",
        { class: "enc-standoff" },
        numberField(null, "X", { range: "standoffX", value: s.x, onValue: (v) => update(i, "x", v), unit: "" }),
        numberField(null, "Y", { range: "standoffY", value: s.y, onValue: (v) => update(i, "y", v), unit: "" }),
        numberField(null, t("dim.height"), {
          range: "standoffHeight",
          value: s.height,
          onValue: (v) => update(i, "height", v),
          unit: "",
        }),
        numberField(null, t("pcb.postDia"), {
          range: "standoffOuterDia",
          value: s.outerDia,
          onValue: (v) => update(i, "outerDia", v),
          unit: "",
        }),
        numberField(null, t("screw.holeDia"), {
          range: "standoffInnerDia",
          value: s.innerDia,
          onValue: (v) => update(i, "innerDia", v),
          unit: "",
        }),
        el("button", {
          class: "enc-icon-btn enc-tiny",
          type: "button",
          title: t("act.remove"),
          "aria-label": `Remove standoff ${i + 1}`,
          html: ICONS.close,
          onclick: () => {
            remember();
            params = { ...params, pcbPreset: "none", pcbStandoffs: list.filter((_, j) => j !== i) };
            afterChange(true);
          },
        }),
      ),
    );
    const add = el(
      "button",
      {
        class: "enc-btn enc-small",
        type: "button",
        onclick: () => {
          remember();
          const last = list[list.length - 1];
          params = {
            ...params,
            pcbStandoffs: [
              ...list,
              {
                id: `s${Date.now().toString(36)}`,
                x: 0,
                y: 0,
                height: last?.height ?? 6,
                outerDia: last?.outerDia ?? 6,
                innerDia: last?.innerDia ?? 2.5,
              },
            ],
          };
          afterChange(true);
        },
      },
      el("span", { html: ICONS.add }),
      t("standoff.add"),
    );
    return el(
      "div",
      { class: "enc-section" },
      rows.length ? rows : el("div", { class: "enc-empty" }, t("standoff.none")),
      el("div", {}, add),
    );
  }

  // Cutouts: a list, and the one being edited open beneath it, changing the model as it's edited.
  let editing = null; // { id, isNew, before }
  const wallLength = (wall) => (wall === "front" || wall === "back" || wall === "lid" ? params.width : params.length);
  const wallTall = (wall) => (wall === "lid" ? params.length : params.height);
  function cutoutName(c) {
    const template = PORTS.find((p) => p.id === c.portTemplate);
    const shape = SHAPES.find(([s]) => s === c.shape)?.[1];
    return c.label || template?.name || (shape ? t(shape) : t("cutout.one"));
  }
  function shapeIcon(c) {
    const w = c.shape === "circle" ? c.diameter : c.width;
    const h = c.shape === "circle" ? c.diameter : c.height;
    const k = Math.min(20 / Math.max(w, 1), 14 / Math.max(h, 1));
    const [sw, sh] = [w * k, h * k];
    const body =
      c.shape === "circle"
        ? `<circle cx="16" cy="12" r="${sw / 2}" />`
        : c.shape === "dsub"
          ? `<path d="M${16 - sw / 2} ${12 - sh / 2}h${sw}l-${sw * 0.12} ${sh}h-${sw * 0.76}z" />`
          : `<rect x="${16 - sw / 2}" y="${12 - sh / 2}" width="${sw}" height="${sh}" rx="${c.shape === "type-c" ? sh / 2 : 1}" />`;
    return `<svg class="enc-shape" viewBox="0 0 32 24" aria-hidden="true"><rect x="1" y="1" width="30" height="22" rx="4" fill="none" stroke="currentColor" stroke-opacity=".3"/><g fill="currentColor" opacity=".75">${body}</g></svg>`;
  }
  function setCutout(id, patch) {
    remember();
    params = { ...params, cutouts: params.cutouts.map((c) => (c.id === id ? { ...c, ...patch } : c)) };
    afterChange(false);
  }
  function addCutout() {
    remember();
    const port = PORTS.find((p) => p.id === "usb-c");
    const cutout = {
      id: `c${Date.now().toString(36)}`,
      wall: "front",
      shape: port.shape,
      width: port.width,
      height: port.height,
      diameter: 8,
      rotation: 0,
      x: round(params.width / 2),
      z: round(params.height / 2),
      portTemplate: port.id,
      label: "",
      labelPosition: "above",
      labelSize: 3.5,
    };
    editing = { id: cutout.id, isNew: true, before: null };
    params = { ...params, cutouts: [...params.cutouts, cutout] };
    afterChange(true);
  }
  function editCutout(id) {
    editing = { id, isNew: false, before: JSON.stringify(params.cutouts.find((c) => c.id === id)) };
    renderForm();
  }
  function removeCutout(id) {
    remember();
    if (editing?.id === id) editing = null;
    params = { ...params, cutouts: params.cutouts.filter((c) => c.id !== id) };
    afterChange(true);
  }
  function duplicateCutout(id) {
    const c = params.cutouts.find((x) => x.id === id);
    if (!c) return;
    remember();
    const copy = { ...c, id: `c${Date.now().toString(36)}`, x: round(Math.min(wallLength(c.wall), c.x + 10)) };
    params = { ...params, cutouts: [...params.cutouts, copy] };
    editing = { id: copy.id, isNew: true, before: null };
    afterChange(true);
  }
  const cutoutActions = (c) => [
    { label: t("act.edit"), icon: ICONS.edit, run: () => editCutout(c.id) },
    { label: t("act.duplicate"), icon: ICONS.copy, run: () => duplicateCutout(c.id) },
    "divider",
    { label: t("act.remove"), icon: ICONS.remove, danger: true, run: () => removeCutout(c.id) },
  ];

  function cutoutList() {
    const items = params.cutouts.map((c) => {
      const size = c.shape === "circle" ? `Ø ${fmt(c.diameter)}` : `${fmt(c.width)} × ${fmt(c.height)}`;
      const row = el(
        "li",
        {
          class: "enc-item",
          tabindex: "0",
          "aria-current": String(editing?.id === c.id),
          "aria-label": `${cutoutName(c)}, ${t(WALL_NAMES[c.wall])}, ${size} mm`,
          onclick: () => editCutout(c.id),
          oncontextmenu: (event) => {
            event.preventDefault();
            openMenu({ x: event.clientX, y: event.clientY }, cutoutActions(c));
          },
          onkeydown: (event) => {
            if (event.target !== event.currentTarget) return;
            if (event.key === "Enter" || event.key === " ") editCutout(c.id);
            else if (event.key === "Delete" || event.key === "Backspace") removeCutout(c.id);
            else return;
            event.preventDefault();
          },
        },
        el("span", { html: shapeIcon(c), style: "color:var(--accent);display:grid" }),
        el(
          "span",
          {},
          el("b", {}, cutoutName(c)),
          el("small", {}, `${t(WALL_NAMES[c.wall])} · ${size} mm · ${t("cutout.at", { x: fmt(c.x), z: fmt(c.z) })}`),
        ),
        el("button", {
          class: "enc-icon-btn enc-tiny",
          type: "button",
          title: t("act.more"),
          "aria-label": `More for ${cutoutName(c)}`,
          "aria-haspopup": "menu",
          html: ICONS.more,
          onclick: (event) => {
            event.stopPropagation();
            openMenu(event.currentTarget, cutoutActions(c));
          },
        }),
      );
      return row;
    });
    const editingCutout = params.cutouts.find((c) => c.id === editing?.id);
    return el(
      "div",
      { class: "enc-section" },
      items.length ? el("ul", { class: "enc-list" }, items) : el("div", { class: "enc-empty" }, t("cutout.none")),
      editingCutout ? cutoutEditor(editingCutout) : null,
    );
  }

  function cutoutEditor(c) {
    const isLid = c.wall === "lid";
    const select = el(
      "select",
      { "aria-label": t("cutout.socketOrShape") },
      el(
        "optgroup",
        { label: t("shape.title") },
        SHAPES.map(([s, label]) => el("option", { value: `shape:${s}` }, t(label))),
      ),
      [...new Set(PORTS.map((p) => p.group))].map((group) =>
        el(
          "optgroup",
          { label: t(group) },
          PORTS.filter((p) => p.group === group).map((p) => el("option", { value: `port:${p.id}` }, p.name)),
        ),
      ),
    );
    select.value = c.portTemplate ? `port:${c.portTemplate}` : `shape:${c.shape}`;
    select.addEventListener("change", () => {
      const [kind, value] = select.value.split(":");
      if (kind === "port") {
        const port = PORTS.find((p) => p.id === value);
        setCutout(c.id, {
          portTemplate: port.id,
          shape: port.shape,
          ...(port.shape === "circle" ? { diameter: port.diameter } : { width: port.width, height: port.height }),
        });
      } else setCutout(c.id, { portTemplate: null, shape: value });
      renderForm();
    });
    const field = (key, label, range, unit = "mm") =>
      numberField(null, label, {
        range,
        unit,
        value: c[key],
        onValue: (v) =>
          setCutout(c.id, {
            [key]: v,
            ...(key === "width" || key === "height" || key === "diameter" ? { portTemplate: null } : {}),
          }),
      });
    const done = () => {
      editing = null;
      renderForm();
    };
    const cancel = () => {
      remember();
      if (editing.isNew) params = { ...params, cutouts: params.cutouts.filter((x) => x.id !== c.id) };
      else if (editing.before) {
        const before = JSON.parse(editing.before);
        params = { ...params, cutouts: params.cutouts.map((x) => (x.id === c.id ? before : x)) };
      }
      editing = null;
      afterChange(true);
    };
    return el(
      "div",
      { class: "enc-editor", onkeydown: (event) => event.key === "Escape" && (event.stopPropagation(), cancel()) },
      segmented(
        t("part.wall"),
        Object.entries(WALL_NAMES).map(([id, label]) => [id, t(label)]),
        c.wall,
        (wall) => {
          setCutout(c.id, { wall, x: round(wallLength(wall) / 2), z: round(wallTall(wall) / 2) });
          renderForm();
        },
      ),
      el(
        "label",
        { class: "enc-field" },
        el("span", {}, t("cutout.socketOrShape")),
        el("div", { class: "enc-input" }, select),
      ),
      c.shape === "circle"
        ? grid(3, field("diameter", t("dim.diameter"), "cutoutDiameter"))
        : grid(
            3,
            field("width", t("dim.width"), "cutoutWidth"),
            field("height", t("dim.height"), "cutoutHeight"),
            field("rotation", t("pcb.turned"), "cutoutRotation", "°"),
          ),
      grid(
        2,
        numberField(null, t("pos.fromLeft"), {
          range: "cutoutPosition",
          value: c.x,
          onValue: (v) => setCutout(c.id, { x: v }),
          title: `0 to ${fmt(wallLength(c.wall))} mm`,
        }),
        numberField(null, isLid ? t("pos.fromFront") : t("pos.fromBottom"), {
          range: "cutoutPosition",
          value: c.z,
          onValue: (v) => setCutout(c.id, { z: v }),
          title: `0 to ${fmt(wallTall(c.wall))} mm`,
        }),
      ),
      textInput(null, t("cutout.label"), {
        value: c.label,
        onValue: (v) => setCutout(c.id, { label: v }),
        maxlength: 16,
        placeholder: "e.g. USB, 12V",
      }),
      c.label
        ? grid(
            2,
            segmented(
              t("cutout.labelGoes"),
              [
                ["above", t("pos.above")],
                ["below", t("pos.below")],
                ["left", t("side.left")],
                ["right", t("side.right")],
              ],
              c.labelPosition,
              (labelPosition) => {
                setCutout(c.id, { labelPosition });
                renderForm();
              },
            ),
            numberField(null, t("cutout.labelSize"), {
              range: "cutoutLabelSize",
              value: c.labelSize,
              onValue: (v) => setCutout(c.id, { labelSize: v }),
            }),
          )
        : null,
      el(
        "div",
        { class: "enc-editor-actions" },
        el("button", { class: "enc-btn enc-small", type: "button", onclick: cancel }, t("act.cancel")),
        el(
          "button",
          { class: "enc-btn enc-small enc-primary", type: "button", onclick: done },
          editing.isNew ? t("act.add") : t("act.done"),
        ),
      ),
    );
  }

  const tabs = $("tabs");
  function renderTabs() {
    tabs.replaceChildren(
      ...TABS.map(([id, label]) =>
        el(
          "button",
          {
            type: "button",
            role: "tab",
            id: `enc-tab-${id}`,
            "aria-selected": String(view.tab === id),
            tabindex: view.tab === id ? "0" : "-1",
            onclick: () => {
              view.tab = id;
              editing = null;
              renderTabs();
              renderForm();
              persist();
            },
            onkeydown: (event) => {
              const i = TABS.findIndex(([t]) => t === id);
              const step = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
              if (!step) return;
              event.preventDefault();
              view.tab = TABS[(i + step + TABS.length) % TABS.length][0];
              renderTabs();
              renderForm();
              tabs.querySelector(`#enc-tab-${view.tab}`)?.focus();
            },
          },
          t(label),
        ),
      ),
    );
  }
  const form = $("form");
  function renderForm() {
    // Keeps focus on the same field when the form is drawn again around it.
    const active = form.contains(document.activeElement) ? document.activeElement.getAttribute("aria-label") : null;
    const scroll = form.scrollTop;
    form.setAttribute("aria-labelledby", `enc-tab-${view.tab}`);
    form.replaceChildren(...TAB_CONTENT[view.tab]().filter(Boolean));
    form.scrollTop = scroll;
    if (active)
      [...form.querySelectorAll("[aria-label]")].find((n) => n.getAttribute("aria-label") === active)?.focus();
  }

  // ---- the bar -----------------------------------------------------------------------------------------------
  const nameInput = $("name");
  nameInput.value = name;
  nameInput.addEventListener("input", () => {
    name = nameInput.value;
    persist();
    updateBar();
  });
  nameInput.addEventListener("change", () => {
    if (!nameInput.value.trim()) nameInput.value = name = UNTITLED;
    updateBar();
  });
  function updateBar() {
    $("dirty").hidden = !dirty();
    $("undo").disabled = !past.length;
    $("redo").disabled = !future.length;
    $("saveModel").disabled = !model?.base?.length;
  }
  $("undo").addEventListener("click", undo);
  $("redo").addEventListener("click", redo);
  $("reset").addEventListener(
    "click",
    safely(async () => {
      if (
        !(await ui.confirm({
          title: t("reset.title"),
          message: t("reset.body"),
        }))
      )
        return;
      remember();
      lastMark = 0;
      params = structuredClone(DEFAULTS);
      editing = null;
      afterChange(true);
    }),
  );

  function safely(fn) {
    return async (...args) => {
      try {
        await fn(...args);
      } catch (err) {
        ui.toast(err?.message || String(err), "error");
      }
    };
  }

  // ---- projects ----------------------------------------------------------------------------------------------
  const readIndex = async () => {
    const list = await storage.get("projects");
    return Array.isArray(list) ? list : [];
  };
  const summary = (p) => `${fmt(p.width)} × ${fmt(p.length)} × ${fmt(p.height)} mm`;

  const saveProject = safely(async () => {
    const id = projectId ?? `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
    name = nameInput.value.trim() || UNTITLED;
    nameInput.value = name;
    const previous = projectId ? await storage.get(`project:${id}`) : null;
    const record = { id, name, params, updatedAt: new Date().toISOString(), modelId: previous?.modelId ?? null };
    await storage.set(`project:${id}`, record);
    const index = (await readIndex()).filter((p) => p.id !== id);
    index.unshift({ id, name, size: summary(params), updatedAt: record.updatedAt });
    await storage.set("projects", index);
    projectId = id;
    saved = JSON.parse(stateJson());
    persist();
    updateBar();
    ui.toast(`Saved ${name}`, "success");
    if (!$("projectsDialog").hidden) await renderProjects();
  });

  const confirmLeave = async (what) =>
    !dirty() ||
    ui.confirm({ title: t("projects.leaveTitle"), message: `${name} has changes that aren't saved. ${what} anyway?` });

  function load(record) {
    params = normalize(record.params).params;
    name = record.name || UNTITLED;
    projectId = record.id ?? null;
    saved = record.id ? JSON.parse(stateJson()) : null;
    nameInput.value = name;
    past.length = 0;
    future.length = 0;
    editing = null;
    firstShow = true;
    afterChange(true);
  }

  const openProject = safely(async (id) => {
    if (id === projectId) return closeProjects();
    if (!(await confirmLeave(t("projects.openAnother")))) return;
    const record = await storage.get(`project:${id}`);
    if (!record) {
      ui.toast(t("projects.gone"), "warning");
      await renderProjects();
      return;
    }
    load(record);
    closeProjects();
    ui.toast(`Opened ${record.name}`, "success");
  });

  const duplicateProject = safely(async (id) => {
    const record = await storage.get(`project:${id}`);
    if (!record) return;
    const copy = {
      ...record,
      id: `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
      name: `${record.name} copy`,
      updatedAt: new Date().toISOString(),
      modelId: null,
    };
    await storage.set(`project:${copy.id}`, copy);
    const index = await readIndex();
    index.unshift({ id: copy.id, name: copy.name, size: summary(copy.params), updatedAt: copy.updatedAt });
    await storage.set("projects", index);
    await renderProjects();
  });

  const exportProject = safely(async (id) => {
    const record = id === projectId || !id ? { name, params } : await storage.get(`project:${id}`);
    if (!record) return;
    thingport.download({
      name: `${slugOf(record.name)}.json`,
      data: JSON.stringify(
        { app: "thingport-enclosure", version: 1, name: record.name, params: record.params },
        null,
        2,
      ),
      type: "application/json",
    });
  });

  const deleteProject = safely(async (id) => {
    const index = await readIndex();
    const entry = index.find((p) => p.id === id);
    if (
      !(await ui.confirm({
        title: `Delete ${entry?.name ?? t("projects.thisProject")}?`,
        message: t("projects.deleteBody"),
      }))
    )
      return;
    await storage.remove(`project:${id}`);
    await storage.set(
      "projects",
      index.filter((p) => p.id !== id),
    );
    if (id === projectId) {
      projectId = null;
      saved = null;
      persist();
      updateBar();
    }
    const row = $("projectList").querySelector(`[data-id="${id}"]`);
    const finish = () => void renderProjects();
    if (row && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      row.classList.add("enc-leaving");
      row.addEventListener("animationend", finish, { once: true });
    } else finish();
    ui.toast(`Deleted ${entry?.name ?? t("projects.theProject")}`, "success");
  });

  const projectActions = (p) => [
    { label: t("act.open"), icon: ICONS.open, run: () => openProject(p.id) },
    { label: t("act.duplicate"), icon: ICONS.copy, run: () => duplicateProject(p.id) },
    { label: t("act.downloadJson"), icon: ICONS.json, run: () => exportProject(p.id) },
    "divider",
    { label: "Delete", icon: ICONS.remove, danger: true, run: () => deleteProject(p.id) },
  ];

  async function renderProjects() {
    const list = $("projectList");
    let index;
    try {
      index = await readIndex();
    } catch (err) {
      list.replaceChildren(el("li", { class: "enc-empty" }, err?.message || String(err)));
      return;
    }
    if (!index.length) {
      list.replaceChildren(
        el(
          "li",
          { class: "enc-empty" },
          t("projects.none"),
          el(
            "button",
            { class: "enc-link", type: "button", onclick: () => void saveProject() },
            t("projects.saveThisOne"),
          ),
        ),
      );
      return;
    }
    list.replaceChildren(
      ...index
        .slice()
        .sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)))
        .map((p, i) =>
          el(
            "li",
            {
              class: "enc-project",
              "data-id": p.id,
              tabindex: "0",
              style: `animation-delay:${Math.min(i * 30, 240)}ms`,
              "aria-current": String(p.id === projectId),
              "aria-label": t("projects.itemAria", { name: p.name, size: p.size, when: ago(p.updatedAt, t) }),
              onclick: () => openProject(p.id),
              oncontextmenu: (event) => {
                event.preventDefault();
                openMenu({ x: event.clientX, y: event.clientY }, projectActions(p));
              },
              onkeydown: (event) => {
                if (event.target !== event.currentTarget) return;
                if (event.key === "Enter" || event.key === " ") openProject(p.id);
                else if (event.key === "Delete") deleteProject(p.id);
                else if (event.key === "ArrowDown") event.currentTarget.nextElementSibling?.focus();
                else if (event.key === "ArrowUp") event.currentTarget.previousElementSibling?.focus();
                else return;
                event.preventDefault();
              },
            },
            el("span", { class: "enc-box-icon", html: ICONS.box }),
            el(
              "span",
              {},
              el("b", {}, p.name),
              el(
                "small",
                {},
                `${p.size} · ${t("projects.savedWhen", { when: ago(p.updatedAt, t) })}${p.id === projectId ? ` · ${t("projects.openNow")}` : ""}`,
              ),
            ),
            el("button", {
              class: "enc-icon-btn",
              type: "button",
              title: t("act.more"),
              "aria-label": `More for ${p.name}`,
              "aria-haspopup": "menu",
              html: ICONS.more,
              onclick: (event) => {
                event.stopPropagation();
                openMenu(event.currentTarget, projectActions(p));
              },
            }),
          ),
        ),
    );
  }

  const dialog = $("projectsDialog");
  async function openProjects() {
    dialog.hidden = false;
    $("projectList").replaceChildren(
      ...Array.from({ length: 3 }, () => el("li", { class: "enc-project", style: "height:56px;opacity:.5" })),
    );
    await renderProjects();
    ($("projectList").querySelector(".enc-project") ?? $("new")).focus();
  }
  function closeProjects() {
    dialog.hidden = true;
    $("projects").focus();
  }
  $("projects").addEventListener("click", () => void openProjects());
  $("projectsClose").addEventListener("click", closeProjects);
  dialog.addEventListener("click", (event) => event.target === dialog && closeProjects());
  dialog.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !menu.hidden) return;
    event.preventDefault();
    event.stopPropagation();
    closeProjects();
  });
  $("new").addEventListener(
    "click",
    safely(async () => {
      if (!(await confirmLeave(t("projects.startNew")))) return;
      load({ id: null, name: UNTITLED, params: DEFAULTS });
      saved = JSON.parse(stateJson());
      updateBar();
      closeProjects();
    }),
  );
  const importFile = $("importFile");
  $("import").addEventListener("click", () => importFile.click());
  importFile.addEventListener(
    "change",
    safely(async () => {
      const file = importFile.files?.[0];
      importFile.value = "";
      if (!file) return;
      let data;
      try {
        data = JSON.parse(await file.text());
      } catch {
        throw new Error(`${file.name} isn't a project: it's not JSON`);
      }
      // Ours ({ name, params }), PrintCasing's ({ version, params }), or the settings alone.
      const raw =
        data && typeof data === "object" && data.params && typeof data.params === "object" ? data.params : data;
      if (!raw || typeof raw !== "object" || !("width" in raw || "height" in raw || "length" in raw))
        throw new Error(`${file.name} doesn't look like an enclosure project`);
      if (!(await confirmLeave(t("act.import")))) return;
      load({ id: null, name: data.name || file.name.replace(/\.json$/i, ""), params: raw });
      closeProjects();
      ui.toast(`Imported ${name}: save it to keep it here`, "success");
    }),
  );

  // ---- downloads and saving to Thingport ---------------------------------------------------------------------
  const files = () => {
    const slug = slugOf(name);
    const out = [{ name: `${slug}-base.stl`, data: stl(model.base, `${name} base`), type: "model/stl" }];
    if (model.lid.length)
      out.push({ name: `${slug}-lid.stl`, data: stl(lidForPrint(model.lid), `${name} lid`), type: "model/stl" });
    return out;
  };

  $("download").addEventListener("click", (event) => {
    const button = event.currentTarget;
    openMenu(button, [
      {
        label: t("file.baseStl"),
        icon: ICONS.stl,
        run: safely(async () => (await ready(), thingport.download(files()[0]))),
      },
      {
        label: t("file.lidStl"),
        icon: ICONS.stl,
        disabled: !params.hasLid,
        run: safely(async () => {
          await ready();
          const lid = files()[1];
          if (lid) thingport.download(lid);
        }),
      },
      "divider",
      { label: t("file.projectJson"), icon: ICONS.json, run: () => exportProject(null) },
    ]);
  });

  function describe() {
    const p = model.params;
    const s = model.stats;
    const parts = files();
    const lines = [
      `An enclosure ${s.outer.map(fmt).join(" × ")} mm outside${p.hasLid ? ", with its lid" : ""}, ${s.inner.map(fmt).join(" × ")} mm inside. Made with Thingport's enclosure generator.`,
      "",
      "## What to print",
      "",
      "| Part | File | How |",
      "| --- | --- | --- |",
      `| Base | \`${parts[0].name}\` | Open side up, no supports |`,
    ];
    if (parts[1]) lines.push(`| Lid | \`${parts[1].name}\` | Turned over, its top on the bed |`);
    lines.push("", `About ${Math.round(s.grams)} g of PLA in all, printed solid.`, "", "## Settings", "");
    lines.push(
      `- Walls ${fmt(p.thickness)} mm, corners rounded ${fmt(p.radius)} mm${p.hasLid ? `, ${fmt(p.tolerance)} mm of room for the lid` : ""}`,
    );
    if (p.hasLid) {
      const lip = p.lidType === "lip" ? ` with a ${fmt(p.lidLipHeight)} mm lip` : "";
      const fixing =
        p.lidFixation === "snap"
          ? `held by ${p.latchCount} snap latch${p.latchCount === 1 ? "" : "es"} on each of the ${(p.latchWalls.length ? p.latchWalls : ["left", "right"]).join(", ")} walls`
          : p.lidFixation === "snapJoint"
            ? t("join.heldBySnap")
            : p.hasCornerScrews
              ? `screwed at the corners: ${fmt(p.screwDiameter)} mm holes in the base, ${fmt(p.lidScrewDiameter)} mm in the lid, for heads up to ${fmt(p.screwHeadDiameter)} mm`
              : t("join.restingInPlace");
      lines.push(`- Lid ${fmt(p.lidThickness)} mm${lip}, ${fixing}`);
    }
    if (p.hasPcbStandoffs) {
      const board = BOARDS.find((b) => b.id === p.pcbPreset);
      const count = p.standoffMode === "list" ? p.pcbStandoffs.length : 4;
      lines.push(
        `- ${count} PCB standoffs${board ? ` for a ${board.name}` : ""} on the ${p.pcbOnLid ? "lid" : "base"}`,
      );
    }
    for (const c of p.cutouts) {
      const size = c.shape === "circle" ? `Ø ${fmt(c.diameter)} mm` : `${fmt(c.width)} × ${fmt(c.height)} mm`;
      lines.push(`- ${cutoutName(c)} (${size}) in the ${c.wall === "lid" ? "lid" : `${c.wall} wall`}`);
    }
    const ventsIn = [...(p.hasVentilation && p.hasLid ? ["lid"] : []), ...p.ventWalls.map((w) => `${w} wall`)];
    if (ventsIn.length)
      lines.push(
        `- ${p.ventPattern === "slots" ? t("vent.title") : `${p.ventPattern[0].toUpperCase()}${p.ventPattern.slice(1)} vents`} in the ${ventsIn.join(", ")}`,
      );
    if (p.hasText && p.textString.trim())
      lines.push(
        `- "${p.textString}" ${p.textType === "emboss" ? t("text.raisedOn") : t("text.cutIntoLower")} the ${p.textPlacement === "lid" ? "lid" : `${p.textPlacement} wall`}`,
      );
    return lines.join("\n");
  }

  const status = $("status");
  function showStatus(message, actions = []) {
    status.hidden = false;
    status.replaceChildren(
      el("span", {}, message),
      ...actions.map(([label, run]) => el("button", { class: "enc-link", type: "button", onclick: run }, label)),
    );
  }

  $("saveModel").addEventListener(
    "click",
    safely(async () => {
      const button = $("saveModel");
      button.disabled = true;
      try {
        await ready();
        if (!model?.base?.length) throw new Error(t("save.nothingYet"));
        const created = await models.create({
          name: name.trim() || UNTITLED,
          description: describe(),
          tags: ["enclosure", "case"],
          files: files(),
        });
        try {
          const picture = await viewer?.snapshot(900, theme.paper);
          if (picture)
            await models.addImages(created.id, [{ name: `${slugOf(name)}.png`, data: picture, type: "image/png" }]);
        } catch {
          // The model stands without its picture.
        }
        if (projectId) {
          const record = await storage.get(`project:${projectId}`);
          if (record) await storage.set(`project:${projectId}`, { ...record, modelId: created.id });
        }
        ui.toast(`Saved ${created.name} to Thingport`, "success");
        showStatus(`Saved as ${created.name}.`, [
          [t("save.openIt"), () => models.open(created.id)],
          [
            t("save.addToCollection"),
            safely(async () => {
              const collection = await ui.pickCollection({ title: `Add ${created.name} to` });
              if (!collection) return;
              await thingport.collections.add(collection.id, [created.id]);
              ui.toast(`Added to ${collection.name}`, "success");
            }),
          ],
        ]);
      } finally {
        button.disabled = false;
      }
    }),
  );

  // ---- menus -------------------------------------------------------------------------------------------------
  const menu = $("menu");
  let menuReturn = null;
  function openMenu(anchor, entries) {
    closeMenu();
    menuReturn = anchor instanceof Element ? anchor : document.activeElement;
    menu.replaceChildren(
      ...entries.map((entry) => {
        if (entry === "divider") return document.createElement("hr");
        const button = el("button", {
          type: "button",
          role: "menuitem",
          tabindex: "-1",
          class: entry.danger ? "enc-danger" : null,
          html: `${entry.icon}<span>${escapeHtml(entry.label)}</span>`,
        });
        button.disabled = Boolean(entry.disabled);
        button.addEventListener("click", () => {
          closeMenu();
          entry.run();
        });
        return button;
      }),
    );
    menu.hidden = false;
    const box = shell.getBoundingClientRect();
    const point =
      anchor instanceof Element
        ? (() => {
            const r = anchor.getBoundingClientRect();
            return { x: r.right - menu.offsetWidth, y: r.bottom + 4 };
          })()
        : anchor;
    menu.style.left = `${Math.max(8, Math.min(point.x - box.left, box.width - menu.offsetWidth - 8))}px`;
    menu.style.top = `${Math.max(8, Math.min(point.y - box.top, box.height - menu.offsetHeight - 8))}px`;
    menu.querySelector("button:not(:disabled)")?.focus();
    setTimeout(() => document.addEventListener("pointerdown", onOutside, true));
  }
  function closeMenu({ restore = false } = {}) {
    if (menu.hidden) return;
    menu.hidden = true;
    document.removeEventListener("pointerdown", onOutside, true);
    if (restore) menuReturn?.focus?.();
  }
  const onOutside = (event) => {
    if (!menu.contains(event.target)) closeMenu();
  };
  menu.addEventListener("keydown", (event) => {
    const buttons = [...menu.querySelectorAll("button:not(:disabled)")];
    const at = buttons.indexOf(document.activeElement);
    const go = (i) => buttons[(i + buttons.length) % buttons.length]?.focus();
    if (event.key === "ArrowDown") go(at + 1);
    else if (event.key === "ArrowUp") go(at - 1);
    else if (event.key === "Home") go(0);
    else if (event.key === "End") go(buttons.length - 1);
    else if (event.key === "Escape" || event.key === "Tab") closeMenu({ restore: true });
    else return;
    event.preventDefault();
    // Escape closes the menu, not the tool's window around it.
    event.stopPropagation();
  });

  // ---- keys --------------------------------------------------------------------------------------------------
  const onKey = (event) => {
    if (!(event.ctrlKey || event.metaKey)) return;
    const key = event.key.toLowerCase();
    const typing =
      /^(input|textarea|select)$/i.test(event.target.tagName) &&
      event.target.type !== "range" &&
      event.target.type !== "checkbox";
    if (key === "s") {
      event.preventDefault();
      void saveProject();
    } else if (!typing && key === "z" && !event.shiftKey) {
      event.preventDefault();
      undo();
    } else if (!typing && (key === "y" || (key === "z" && event.shiftKey))) {
      event.preventDefault();
      redo();
    }
  };
  shell.addEventListener("keydown", onKey);
  $("saveProject").addEventListener("click", () => void saveProject());

  renderTabs();
  renderForm();
  // The window's own words, before the first render.
  labels();
  renderViewControls();
  updateBar();
  await build();

  return () => {
    closed = true;
    clearTimeout(buildTimer);
    clearTimeout(draftTimer);
    closeMenu();
    void storage.set("draft", { name, params, projectId, saved, view }).catch(() => undefined);
    shell.removeEventListener("keydown", onKey);
    viewer?.dispose();
  };
}
